class PayrollPage extends StatefulWidget{const PayrollPage({super.key,this.businessId});final String? businessId;@override State<PayrollPage> createState()=>_PayrollPageState();}
class _PayrollPageState extends State<PayrollPage>{final _repo=PayrollRepository();late Future<List<PayrollRecord>> _future;@override void initState(){super.initState();_future=_load();}Future<List<PayrollRecord>> _load()=>widget.businessId==null?Future.value(const[]):_repo.load(widget.businessId!);Future<void> _refresh()async{setState(()=>_future=_load());await _future;}
