@override Widget build(BuildContext c){final m=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return RefreshIndicator(onRefresh:_refresh,child:FutureBuilder<List<PayrollRecord>>(future:_future,builder:(c,s){final rows=s.data??const <PayrollRecord>[];final total=rows.fold<double>(0,(a,e)=>a+e.netAmount);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[IrkopSectionHeader(eyebrow:'OPERASIONAL',title:'Gaji Karyawan',subtitle:'Kelola periode, nominal dan status pembayaran.',icon:Icons.badge_outlined,action:'Tambah',onAction:()=>_edit()),const SizedBox(height:14),Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.payments_outlined)),title:const Text('Total data gaji'),subtitle:Text(rows.length.toString()+' periode tercatat'),trailing:Text(m.format(total),style:const TextStyle(fontWeight:FontWeight.w800)))),const SizedBox(height:12),if(s.connectionState!=ConnectionState.done)const LinearProgressIndicator(),if(s.hasError)Text('Gagal memuat gaji: '+s.error.toString()),if(!s.hasError&&s.connectionState==ConnectionState.done&&rows.isEmpty)const EmptyStateCard(icon:Icons.badge_outlined,title:'Belum ada data gaji',subtitle:'Tambahkan pembayaran gaji pertama.'),...rows.map((e)=>Card(margin:const EdgeInsets.only(bottom:10),child:ListTile(onTap:()=>_edit(e),leading:CircleAvatar(child:Text(e.employeeName.isEmpty?'K':e.employeeName[0].toUpperCase())),title:Text(e.employeeName,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(DateFormat('MMMM yyyy','id_ID').format(e.period)+(e.paidAt==null?' • Belum dibayar':' • Sudah dibayar')),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.end,children:[Text(m.format(e.netAmount),style:const TextStyle(fontWeight:FontWeight.w800)),TextButton(onPressed:()=>_repo.markPaid(id:e.id,businessId:widget.businessId!,paid:e.paidAt==null).then((_)=>_refresh()),child:Text(e.paidAt==null?'Tandai bayar':'Batal bayar'))]))))]); })); } }